<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,nextTick} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>,hosts:Row[]}>()
const site=ref<Row>({domain:'',https:true}),services=ref<Row[]>([]),shares=ref<Row[]>([]),busy=ref(false),error=ref(''),secretURL=ref(''),notice=ref('')
const form=ref({name:'',host_id:'',kind:'shadowsocks',address:'',listen:'127.0.0.1',port:2080,parent_id:'',next_id:'',tunnels:[] as Row[]})
const shareFormat=ref('sing-box')
function formattedShare(){if(!secretURL.value)return '';const url=new URL(secretURL.value);url.searchParams.set('format',shareFormat.value);return url.toString()}
async function copyShare(){try{await navigator.clipboard.writeText(formattedShare());notice.value='已复制所选客户端的订阅链接'}catch{error.value='复制失败，请选中链接手动复制'}}
const subscription=ref({name:'',days:30,service_ids:[] as string[]})
let alive=true
onUnmounted(()=>{alive=false;secretURL.value='';clearTimeout(timer)})
async function action(f:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await f()}catch(e){if(alive)error.value=String(e)}finally{if(alive)busy.value=false}}
async function reload(){const [a,b,c]=await Promise.all([props.api('site'),props.api('live'),props.api('subscriptions')]);if(!alive)return;site.value=a;services.value=b;shares.value=c}
async function refreshRows(){if(document.visibilityState==='hidden'||busy.value)return;await action(async()=>{const [b,c]=await Promise.all([props.api('live'),props.api('subscriptions')]);if(alive){services.value=b;shares.value=c}})}
let timer:ReturnType<typeof setTimeout>
function schedule(){timer=setTimeout(async()=>{await refreshRows();if(alive)schedule()},15000)}
onMounted(()=>{void action(reload);schedule()})
function saveSite(){void action(async()=>{await props.api('site','PUT',{domain:site.value.domain,https:site.value.https});notice.value='域名设置已保存。已安装域名同步器时会自动申请证书并更新网关；否则需运行部署文档中的域名配置命令。';site.value=await props.api('site')})}
function createService(){void action(async()=>{const b:any={...form.value};if(b.kind==='frpc'){b.address='';b.port=2080;b.next_id=''};await props.api('live','POST',b);form.value.name='';await reload();notice.value='服务已创建，默认停用。确认主机、监听地址和防火墙后再启用。'})}
const confirm=ref<Row|null>(null),confirmDialog=ref<HTMLElement|null>(null)
let previousFocus:HTMLElement|null=null
watch(confirm,async value=>{if(value){previousFocus=document.activeElement as HTMLElement;await nextTick();confirmDialog.value?.querySelector<HTMLButtonElement>('button')?.focus()}else previousFocus?.focus()})
watch(()=>form.value.parent_id,async id=>{if(!id||form.value.kind!=='frpc')return;try{const t=await props.api('live/'+id+'/tunnels');if(alive&&form.value.parent_id===id)form.value.tunnels=t}catch(e){if(alive)error.value=String(e)}})
function toggle(row:Row){confirm.value={...row,operation:'toggle'}}
function revoke(row:Row){confirm.value={...row,operation:'revoke'}}
function confirmed(){const row=confirm.value;if(!row)return;confirm.value=null;void action(async()=>{if(row.operation==='toggle')await props.api('live/'+row.id+'/toggle','POST',{enabled:!row.enabled});else await props.api('subscriptions/'+row.id+'/revoke','POST',{});await reload()})}
function createShare(){void action(async()=>{const v=await props.api('subscriptions','POST',subscription.value);secretURL.value=v.url;await reload()})}
async function rotate(row:Row){await action(async()=>{const v=await props.api('subscriptions/'+row.id+'/rotate','POST',{});secretURL.value=v.url;await reload()})}
function hostName(id:string){return props.hosts.find(h=>h.id===id)?.name??id.slice(0,8)}
</script>
<template>
<div class="publish-grid">
<div class="publish-panels" :inert="!!confirm">
 <div v-if="error" class="error" role="alert">{{error}}</div><div v-if="notice" class="form-note" role="status">{{notice}}</div>
 <form class="panel publish-card" @submit.prevent="saveSite"><div class="section-heading"><div><span class="eyebrow">DOMAIN / ACCESS</span><h2>域名与 HTTPS</h2></div><span :class="['status',site.gateway_state==='active'&&site.gateway_domain===site.domain&&site.gateway_https===site.https?'succeeded':'pending']">{{site.gateway_state==='active'&&site.gateway_domain===site.domain&&site.gateway_https===site.https?'网关已回报生效':'网关待同步 / 验证'}}</span></div><p class="muted">订阅链接按这里的域名生成。修改域名后仍需更新 DNS、网关和证书；旧域名可在迁移期保留反向代理。</p><div class="fields"><label>分享域名<input v-model="site.domain" required placeholder="vps.example.com" maxlength="253"></label><label>分享协议<select v-model="site.https"><option :value="true">HTTPS（推荐）</option><option :value="false">HTTP（明文，包含代理凭据）</option></select></label></div><p v-if="!site.https" class="error">HTTP 分享会泄露订阅令牌及代理密码。仅在可信网络临时使用。</p><div class="actions"><button class="primary" :disabled="busy">保存域名设置</button><button class="secondary" type="button" :disabled="busy" @click="action(reload)">刷新状态</button></div></form>
 <section class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">MANAGED SERVICES</span><h2>真实服务</h2></div><span class="status">{{services.length}} 项</span></div><p class="muted">由显式启用 ENABLE_LIVE 的 Agent 运行。无公网 IPv4 的设备可作为 FRP 客户端主动连接；IPv6 地址不加方括号。默认监听回环，公网监听需手动选择并放行防火墙。</p>
 <form @submit.prevent="createService"><div class="fields"><label>名称<input v-model="form.name" required maxlength="100"></label><label>运行主机<select v-model="form.host_id" required><option disabled value="">选择主机</option><option v-for="h in hosts" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>服务类型<select v-model="form.kind"><option value="shadowsocks">Shadowsocks 2022 / sing-box</option><option value="frps">FRP 公网 / IPv6 中继服务端</option><option value="frpc">FRP 内网设备客户端</option></select></label><template v-if="form.kind!=='frpc'"><label>分享或服务端地址<input v-model="form.address" placeholder="域名、IPv4 或 IPv6" required></label><label>监听地址<select v-model="form.listen"><option>127.0.0.1</option><option>::1</option><option>0.0.0.0</option><option>::</option></select></label><label>监听端口<input v-model.number="form.port" type="number" min="1024" max="65535" required></label></template><label v-else>关联 FRP 服务端<select v-model="form.parent_id" required><option value="" disabled>选择服务端</option><option v-for="s in services.filter(s=>s.kind==='frps')" :key="s.id" :value="s.id">{{s.name}} · {{s.address}}</option></select></label><label v-if="form.kind==='shadowsocks'">下一跳（可选）<select v-model="form.next_id"><option value="">直接出站</option><option v-for="s in services.filter(s=>s.kind==='shadowsocks')" :key="s.id" :value="s.id">{{s.name}} · {{s.address}}</option></select></label></div>
 <template v-if="form.kind==='frps'||form.kind==='frpc'"><div class="rules-heading"><h3>FRP TCP 隧道</h3><button v-if="form.kind==='frps'" class="secondary" type="button" :disabled="form.tunnels.length>=64" @click="form.tunnels.push({name:'tunnel-'+(form.tunnels.length+1),local_host:'127.0.0.1',local_port:3000,remote_port:30000})">添加隧道</button></div><div v-for="(t,i) in form.tunnels" :key="i" class="fields tunnel-fields"><label>隧道名<input v-model="t.name" required></label><label>客户端回环目标<select v-model="t.local_host"><option>127.0.0.1</option><option>::1</option></select></label><label>客户端目标端口<input v-model.number="t.local_port" type="number" min="1" max="65535" required></label><label>服务端映射端口<input v-model.number="t.remote_port" type="number" min="1024" max="65535" required></label><button class="text-button" type="button" @click="form.tunnels.splice(i,1)">移除隧道</button></div></template><button class="primary" :disabled="busy">创建并保持停用</button></form>
 <div class="table-scroll"><table><thead><tr><th>服务 / 主机</th><th>地址</th><th>Agent 状态</th><th>操作</th></tr></thead><tbody><tr v-for="s in services" :key="s.id"><td>{{s.name}}<small class="block-muted">{{s.kind}} · {{hostName(s.host_id)}}</small></td><td>{{s.address}} : {{s.port}}</td><td><span :class="['status',s.online?'succeeded':'pending']">{{s.online?'进程运行中':s.enabled?'等待 / '+s.state:'停用'}}</span><small class="block-muted">版本 {{s.reported_version}} / {{s.version}}</small></td><td><button class="text-button" :disabled="busy" @click="toggle(s)">{{s.enabled?'停用':'启用'}}</button></td></tr></tbody></table></div><p v-if="!services.length" class="muted">暂无真实服务。先在主机资产中登记主机并安装 Agent。</p><small class="muted">“进程运行中”来自 45 秒内的 Agent 回报，不代表公网、DNS 或防火墙已验证。停用将阻止新订阅下载并等待 Agent 停止进程。</small></section>
 <section class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">SUBSCRIPTIONS / SHARE</span><h2>订阅与分享</h2></div></div><form @submit.prevent="createShare"><div class="fields"><label>订阅名称<input v-model="subscription.name" required maxlength="100"></label><label>有效天数<input v-model.number="subscription.days" type="number" min="1" max="365" required></label></div><div class="service-choices"><label v-for="s in services.filter(s=>s.kind==='shadowsocks')" :key="s.id" class="check-label"><input v-model="subscription.service_ids" type="checkbox" :value="s.id">{{s.name}} · {{s.address}}</label></div><button class="primary" :disabled="busy||!subscription.service_ids.length">创建分享链接</button></form>
 <div v-if="secretURL" class="credential" role="status"><strong>一次性显示，请妥善保存</strong><label>客户端格式<select v-model="shareFormat" aria-label="订阅客户端格式"><option value="sing-box">sing-box · JSON 配置</option><option value="mihomo">Mihomo / Clash Meta · JSON（兼容 YAML）</option><option value="shadowrocket">Shadowrocket · Base64 URI 列表</option></select></label><input :value="formattedShare()" readonly aria-label="订阅分享链接" @focus="($event.target as HTMLInputElement).select()"><small>手动切换格式后复制对应链接；格式不会根据浏览器或 User-Agent 自动改变。</small><button class="primary" @click="copyShare">复制所选格式链接</button><button class="text-button" @click="secretURL=''">隐藏链接</button></div><p class="muted">撤销或轮换链接只阻止后续下载。已导入客户端的代理密码仍有效；泄露后需停用该服务，并创建新服务替换凭据。</p><div class="table-scroll"><table><thead><tr><th>订阅</th><th>到期时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="s in shares" :key="s.id"><td>{{s.name}}</td><td>{{new Date(s.expires_at).toLocaleString()}}</td><td>{{s.revoked_at?'已撤销':Date.parse(s.expires_at)<Date.now()?'已过期':'有效'}}</td><td><button v-if="!s.revoked_at" class="text-button" :disabled="busy" @click="rotate(s)">轮换链接</button><button v-if="!s.revoked_at" class="text-button" :disabled="busy" @click="revoke(s)">撤销</button></td></tr></tbody></table></div></section>
 </div>
 <div v-if="confirm" class="modal-backdrop"><section ref="confirmDialog" tabindex="-1" class="modal publish-confirm" role="dialog" aria-modal="true" aria-labelledby="publish-confirm-title" @keydown.esc="confirm=null"><div class="modal-heading"><h2 id="publish-confirm-title">确认{{confirm.operation==='revoke'?'撤销订阅':confirm.enabled?'停止服务':'启动真实服务'}}</h2></div><div class="form-content"><p>{{confirm.name}}</p><p>{{confirm.operation==='revoke'?'已有客户端中的代理凭据不会被删除。':confirm.enabled?'停止后连接会中断，Agent 将在下一次同步执行。':'将使用固定引擎启动网络服务。请确认监听地址、端口和防火墙；公网监听会提供对外入口。'}}</p></div><div class="modal-footer"><button class="secondary" @click="confirm=null">取消</button><button class="primary" @click="confirmed">确认执行</button></div></section></div>
</div>
</template>
